function exact_change(coins, amount) {
  const sorted = [...coins].sort((a, b) => a - b);
  const out = [];
  const current = [];
  const build = (start, remaining) => {
    if (remaining === 0) {
      out.push([...current]);
      return;
    }
    for (let i = start; i < sorted.length; i++) {
      const c = sorted[i];
      if (c > remaining) break;
      current.push(c);
      build(i, remaining - c);
      current.pop();
    }
  };
  build(0, amount);
  return out;
}

